  1	// node/vscode_extension/webview-ui/src/App.tsx
  2	import { useEffect, useState, useCallback } from "react";
  3	import { Header } from "./components/Header";
  4	import { ChatArea } from "./components/ChatArea";
  5	import { InputArea } from "./components/inputarea/InputArea";
  6	import { MCPServersModal } from "./components/MCPServersModal";
  7	import { WorkDirModal } from "./components/WorkDirModal";
  8	import { ConfigErrorScreen } from "./components/ConfigErrorScreen";
  9	import { ProjectSetupScreen } from "./components/ProjectSetupScreen";
 10	import { SetupScreen } from "./components/SetupScreen";
 11	import { Toaster, toast } from "./components/ui/sonner";
 12	import { useChatStore, useSettingsStore } from "./stores";
 13	import { bridge, Events } from "./services";
 14	import { useAppInit } from "./hooks/useAppInit";
 15	import { isPreflightError } from "shared/errors";
 16	import type { UIStreamEvent, StreamError, ExtensionConfig } from "shared/types";
 17	import "./styles/index.css";
 18	
 19	function MainContent({ onAuthAction }: { onAuthAction: () => void }) {
 20	  const { processEvent, startNewConversation, sessionId, setTitle } = useChatStore();
 21	  const { setMCPServers, setExtensionConfig, extensionConfig } = useSettingsStore();
 22	
 23	  useEffect(() => {
 24	    // Batch events via requestAnimationFrame to prevent main thread saturation
 25	    // during high-frequency streams (thinking tokens, tool call parts).
 26	    let pendingEvents: UIStreamEvent[] = [];
 27	    let flushScheduled = false;
 28	
 29	    const flush = () => {
 30	      flushScheduled = false;
 31	      const batch = pendingEvents;
 32	      pendingEvents = [];
 33	      if (batch.length === 0) return;
 34	
 35	      // Process all buffered events in a single state update
 36	      for (const event of batch) {
 37	        processEvent(event);
 38	      }
 39	
 40	      // Handle errors from the batch
 41	      for (const event of batch) {
 42	        if (event.type === "error") {
 43	          const streamError = event as StreamError;
 44	          if (isPreflightError(streamError.code || "UNKNOWN")) {
 45	            toast.error(streamError.message);
 46	          }
 47	        }
 48	      }
 49	    };
 50	
 51	    const scheduleFlush = () => {
 52	      if (flushScheduled) return;
 53	      flushScheduled = true;
 54	      if (typeof requestAnimationFrame !== "undefined") {
 55	        requestAnimationFrame(flush);
 56	      } else {
 57	        setTimeout(flush, 0);
 58	      }
 59	    };
 60	
 61	    return bridge.on(Events.StreamEvent, (event: UIStreamEvent) => {
 62	      // 只有当前已有 session 时才过滤，确保 session_start 能正常处理
 63	      if (sessionId && "_sessionId" in event && event._sessionId && event._sessionId !== sessionId) {
 64	        console.log("Ignored stream event from another session:", event._sessionId);
 65	        return;
 66	      }
 67	      pendingEvents.push(event);
 68	      scheduleFlush();
 69	    });
 70	  }, [processEvent, sessionId]);
 71	
 72	  useEffect(() => {
 73	    const unsubs = [
 74	      bridge.on(Events.MCPServersChanged, setMCPServers),
 75	      bridge.on(Events.ExtensionConfigChanged, ({ config }: { config: ExtensionConfig }) => setExtensionConfig(config)),
 76	      bridge.on(Events.FocusInput, () => document.querySelector<HTMLTextAreaElement>("textarea")?.focus()),
 77	      bridge.on(Events.NewConversation, () => startNewConversation()),
 78	      bridge.on(Events.SessionTitleUpdated, ({ sessionId: updatedSessionId, title, source }: { sessionId: string; title: string; source: "user" | "llm" | "fallback" }) => {
 79	        setTitle(updatedSessionId, title, source);
 80	      }),
 81	    ];
 82	    return () => unsubs.forEach((u) => u());
 83	  }, [setMCPServers, setExtensionConfig, startNewConversation, setTitle]);
 84	
 85	  useEffect(() => {
 86	    useChatStore.getState().initTabs();
 87	  }, []);
 88	
 89	  useEffect(() => {
 90	    if (!extensionConfig.enableNewConversationShortcut) return;
 91	    const handler = (e: KeyboardEvent) => {
 92	      if ((e.metaKey || e.ctrlKey) && e.key === "n") {
 93	        e.preventDefault();
 94	        startNewConversation();
 95	      }
 96	    };
 97	    window.addEventListener("keydown", handler);
 98	    return () => window.removeEventListener("keydown", handler);
 99	  }, [extensionConfig.enableNewConversationShortcut, startNewConversation]);
100	
101	  return (
102	    <>
103	      <div className="flex-1 min-h-0 relative group/chat">
104	        <ChatArea />
105	      </div>
106	      <div className="shrink-0 max-h-[80vh] flex flex-col min-h-0">
107	        <InputArea onAuthAction={onAuthAction} />
108	      </div>
109	      <MCPServersModal />
110	      <WorkDirModal />
111	    </>
112	  );
113	}
