115	export default function App() {
116	  const { status, errorMessage, cliResult, modelsCount, refresh } = useAppInit();
117	  const extensionConfig = useSettingsStore((s) => s.extensionConfig);
118	  const [forceShowSetup, setForceShowSetup] = useState(false);
119	
120	  const handleSetupSuccess = useCallback(() => {
121	    setForceShowSetup(false);
122	    refresh();
123	  }, [refresh]);
124	
125	  // Show setup screen if no API key is configured or if explicitly requested
126	  const hasApiKey = !!extensionConfig?.apiKey;
127	  const shouldShowSetup = !hasApiKey || forceShowSetup;
128	
129	  if (shouldShowSetup && status !== "loading" && status !== "cli-error" && status !== "no-workspace") {
130	    return (
131	      <div className="flex flex-col h-screen text-foreground overflow-hidden">
132	        <Header />
133	        <SetupScreen onSetupSuccess={handleSetupSuccess} />
134	        <Toaster position="top-center" />
135	      </div>
136	    );
137	  }
138	
139	  // 如果没有模型
140	  if (modelsCount === 0 && status === "no-models") {
141	    return (
142	      <div className="flex flex-col h-screen text-foreground overflow-hidden">
143	        <Header />
144	        <ConfigErrorScreen type="no-models" cliResult={cliResult} errorMessage={errorMessage} onRefresh={refresh} onOpenSetup={() => setForceShowSetup(true)} />
145	        <Toaster position="top-center" />
146	      </div>
147	    );
148	  }
149	
150	  // 其他错误状态
151	  if (status === "cli-error" || status === "no-workspace") {
152	    return (
153	      <div className="flex flex-col h-screen text-foreground overflow-hidden">
154	        <Header />
155	        <ConfigErrorScreen type={status} cliResult={cliResult} errorMessage={errorMessage} />
156	        <Toaster position="top-center" />
157	      </div>
158	    );
159	  }
160	
161	  // 如果项目未初始化
162	  if (status === "uninitialized") {
163	    return (
164	      <div className="flex flex-col h-screen text-foreground overflow-hidden">
165	        <Header />
166	        <ProjectSetupScreen onSetupComplete={refresh} />
167	        <Toaster position="top-center" />
168	      </div>
169	    );
170	  }
171	
172	  // 正常状态
173	  return (
174	    <div className="flex flex-col h-screen text-foreground overflow-hidden">
175	      <Header />
176	      <MainContent onAuthAction={() => setForceShowSetup(true)} />
177	      <Toaster position="top-center" />
178	    </div>
179	  );
180	}
